"o": [
"先明确谁为沉淀负责、沉淀算谁的绩效",
"先挂到交付部门，等交付压力下降再调整",
"由销售部门牵头，便于第一时间贴近客户",
"先挂到产品部门，由产品经理代替 FDE 去现场"
],
