"c": "ADP（智能体开发平台）为有定制化需求的企业提供低代码/专业代码混合的开发运行环境，构建 Agent、工作流、对话机器人并管理全生命周期。适用：IT 开发团队、AI 应用工程师、技术产品经理；定制化应用与复杂工作流编排；接入第三方 API、数据库、消息队列；多模型切换管理；产物如企业自有 Agent、智能客服、自动化审批流。不适用：纯业务人员、开箱即用的知识问答、简单文档问答、通用知识库助手——这些选 WorkBuddy。",
