"c": "Ardot 是 AI 设计智能体协作平台，对标 Figma 的专业设计编辑能力：①支持 .fig 文件无损导入，其他设计工具格式需先转换；②AI 读取团队组件库与设计规范，生成无「孤儿组件」的高保真 UI 设计稿；③通过设计变量沉淀颜色、数值、字符串等设计令牌，支持多主题切换、多人评论标注与版本对比；④设计稿经内置 MCP 服务器发送至 CodeBuddy，生成 React、Vue、小程序代码，开发者模式提供 iOS/Android 多端标注与代码复制，还原度可达 99% 以上。不适用长视频、音频、工业级高精三维；没有专职设计师、只要成套创意物料时应选 Miora。 风险提示：设计稿进入代码还原前仍需设计师确认组件与设计规范一致性。",
