"c": "WorkBuddy 的核心交付模式是「配置式部署」：客户无需写代码，通过平台界面完成知识库接入、Prompt 模板配置、权限管理即可上线。典型交付路径：①收集文档材料（PDF/Word/网页）→②创建知识库并上传文档，自动向量化→③配置助手角色与 Prompt 模板（如「只基于文档回答」）→④配置哪些部门可访问哪个助手→⑤通过企业微信/Web 入口发布；预期 1～2 周（含文档清洗与测试）。员工端入口为桌面客户端（Mac/Windows）、移动端、小程序；IDE 插件是 CodeBuddy 的入口。",
