"c": "五大工具横向对比：①WorkBuddy——业务员工、定制低、上线 1～2 周、技术门槛低、核心价值知识民主化；②CodeBuddy——开发者、定制低（插件形态）、1 周内、门槛中、研发提效；③ADP——IT/AI 开发团队、定制高、1～3 个月、门槛中高、自主构建 AI 资产；④Miora——创意/设计需求用户、定制中（记忆 + Skills）、即开即用 SaaS、门槛低、创意生产力民主化；⑤Ardot——设计师/产品/研发、定制中（组件库 + 设计变量）、即开即用 SaaS、门槛低～中、设计交付效率与还原度。",
